const action = $input.first().json.action;
if (action === 'list') {
  const events = $input.all()[0].json.items || $input.all()[0].json.value || [];
  const formatted = events.map(e => `${e.summary}: ${e.start?.dateTime || e.start?.date}`).join('
');
  return [{ json: { result: formatted || 'No events found.' } }];
}
return [{ json: { result: `Event created: ${$input.all()[0].json.summary || $input.all()[0].json.subject}` } }];
